arguments.command:
python -I - <<'PY'
import json, glob, math, statistics
files=sorted(glob.glob('/workspace/results/recorded_run/metrics/*.json'))
rows=[]
for f in files:
    d=json.load(open(f)); m={k:float(v) for k,v in d['metrics'].items() if isinstance(v,(int,float)) or (isinstance(v,str) and v not in ('nan','inf','-inf'))}
    rows.append((d['step'],m))
keys=['critic/score/mean','critic/score/max','critic/score/min','response_length/mean','response_length/clip_ratio','num_turns/mean','verl_tool/is_traj_finished/mean','verl_tool/empty_responses/mean','verl_tool/valid_action/mean','verl_tool/retokenization_diff/mean','actor/grad_norm','actor/entropy']
print('STEPS',len(rows),rows[0][0],rows[-1][0])
print('ALL-NEGATIVE STEPS (score max == -1):', [s for s,m in rows if m.get('critic/score/max')==-1])
print('STEPS WITH ANY +1:', [s for s,m in rows if m.get('critic/score/max')==1])
print('MIXED REWARD STEPS:', [s for s,m in rows if m.get('critic/score/max')!=m.get('critic/score/min')])
print('\nEVERY 5 STEPS:')
print('step score mean/max/min resp clip turns finish empty valid retok grad entropy')
for s,m in rows:
    if s%5==0 or s==1:
        vals=[s]+[m.get(k,float('nan')) for k in ['critic/score/mean','critic/score/max','critic/score/min','response_length/mean','response_length/clip_ratio','num_turns/mean','verl_tool/is_traj_finished/mean','verl_tool/empty_responses/mean','verl_tool/valid_action/mean','verl_tool/retokenization_diff/mean','actor/grad_norm','actor/entropy']]
        print('%3d '%s + ' '.join('%8.4g'%v for v in vals[1:]))
print('\nEVALUATIONS:')
for s,m in rows:
    ev={k:v for k,v in m.items() if k.startswith('val-')}
    if ev:
        print('step',s)
        for k,v in ev.items(): print(' ',k,v)
print('\nEXTREMA:')
for k in keys:
    present=[(s,m[k]) for s,m in rows if k in m]
    print(k,'min',min(present,key=lambda x:x[1]),'max',max(present,key=lambda x:x[1]),'first',present[0],'last',present[-1])
