import json
for step in [1,40,80,120,160,200]:
 p=f'/workspace/results/recorded_run/rollouts/{step}.jsonl'
 print('\nSTEP',step)
 for i,line in enumerate(open(p),1):
  d=json.loads(line)
  print('row',i,'keys',list(d))
  for k,v in d.items():
   if isinstance(v,dict): print(' ',k,'dict keys',list(v))
   elif isinstance(v,list): print(' ',k,'list len',len(v),'first type',type(v[0]).__name__ if v else None)
   else:
    r=repr(v); print(' ',k,r[:300]+('...' if len(r)>300 else ''))
