step=1
counts=collections.defaultdict(collections.Counter)
first=collections.defaultdict(dict)
metrics={}
progress={}
lines=open(p,encoding="utf-8",errors="replace").read().splitlines()
for no,raw in enumerate(lines,1):
 s=ansi.sub("",raw)
 m=re.search(r"Dumped generations to .*/(\d+)\.jsonl",s)
 if m:
  step=int(m.group(1))+1
  continue
 if "test_gen_batch meta info:" in s: step="validation_after_200"
 pats={
 "format_neg":r"format reward: -1(?:\.0)?(?:\s|$)",
 "format_zero":r"format reward: 0\.0(?:\s|$)",
 "invalid_format_occ":r"Format Error: Invalid tool call format",
 "missing_separator_occ":r"Format Error: Missing @@ separator",
 "tool_name_error_occ":r"Tool Name Error",
 "decoder_400":r"生成响应时出错.*Error code: 400",
 "tool_retry":r"Tool execution error.*Retry:",
 "crop_failure":r"裁剪图像失败",
 "timeout":r"(?i)timeout|timed out",
 }
 for k,pat in pats.items():
  n=len(re.findall(pat,s))
  if n:
   counts[step][k]+=n
   first[k].setdefault(step,(no,s[:240]))
 m=re.search(r"\(TaskRunner pid=\d+\) step:(\d+) - (.*)",s)
 if m:
  n=int(m.group(1)); d={}
  for part in m.group(2).split(" - "):
   if ":" in part:
    k,v=part.split(":",1)
    try:d[k]=float(v)
    except ValueError:pass
  metrics[n]=(no,d)
 m=re.search(r"Training Progress:.*?(\d+):(\d\d):(\d\d)<",s)
 if m: progress[step-1]=int(m.group(1))*3600+int(m.group(2))*60+int(m.group(3))
print("ERROR_COUNTS_BY_STEP (nonzero; occ=occurrences, not trajectories)")
keys=list(next(iter(counts.values())).keys())
keys=["format_neg","format_zero","invalid_format_occ","missing_separator_occ","tool_name_error_occ","decoder_400","tool_retry","crop_failure","timeout"]
print("step "+" ".join(keys))
for st in sorted((x for x in counts if isinstance(x,int))):
 c=counts[st]
 if any(c[k] for k in keys[2:]): print(st," ".join(str(c[k]) for k in keys))
print("TOTALS", {k:sum(c[k] for c in counts.values()) for k in keys})
print("FIRST_LAST_BY_CATEGORY")
for k in keys[2:]:
 vals=[(st,counts[st][k]) for st in counts if isinstance(st,int) and counts[st][k]]
 if vals: print(k,"first",min(vals),"last",max(vals),"active_steps",len(vals),"first_line",first[k][min(vals)][0])
print("LATE_FORMAT_LOG_LINES")
for st in range(160,201):
 if counts[st]["format_neg"] or counts[st]["format_zero"]: print(st,counts[st]["format_neg"],counts[st]["format_zero"])
print("LATE_METRICS step line score clip finished valid_action resp_mean resp_max turns_mean retok entropy grad")
keys2=["critic/score/mean","response_length/clip_ratio","verl_tool/is_traj_finished/mean","verl_tool/valid_action/mean","response_length/mean","response_length/max","num_turns/mean","verl_tool/retokenization_diff/mean","actor/entropy","actor/grad_norm"]
for st in range(170,201):
 no,d=metrics[st]
 print(st,no," ".join(str(d.get(k)) for k in keys2))
'

