patterns={'traceback':re.compile(r'Traceback'), 'runtime_error':re.compile(r'RuntimeError'), 'cuda_error':re.compile(r'CUDA.*(?:error|out of memory)',re.I), 'exception':re.compile(r'\bException\b'), 'warning':re.compile(r'\bWARNING\b|UserWarning'), 'abort':re.compile(r'abort',re.I), 'overflow':re.compile(r'overflow',re.I)}
counts=collections.Counter(); samples={k:[] for k in patterns}
with open(p,errors='replace') as f:
 for n,line in enumerate(f,1):
  for k,pat in patterns.items():
   if pat.search(line):
    counts[k]+=1
    if len(samples[k])<6: samples[k].append((n,line.strip()[:800]))
print('COUNTS',dict(counts))
for k,v in samples.items():
 if v:
  print('\n',k)
  for n,line in v: print(n,line)
